payload.arguments:
{"cmd":"git status --porcelain=v1 | awk '
BEGIN { tracked=0; untracked=0; ct_tracked=0; ct_untracked=0; unreal_untracked=0; other_untracked=0; other_tracked=0 }
{
  status=substr($0,1,2); path=substr($0,4);
  if (status == "??") {
    untracked++;
    if (path ~ /^\.control-tower\//) ct_untracked++;
    else if (path ~ /^cpp\/unreal_projects\/SpearSim\/Content\/SPEAR\/Scenes\//) unreal_untracked++;
    else other_untracked++;
  } else {
    tracked++;
    if (path ~ /^\.control-tower\//) ct_tracked++;
    else other_tracked++;
  }
}
END {
  printf("tracked_modified=%d\ncontrol_tower_tracked_modified=%d\nother_tracked_modified=%d\nuntracked_total=%d\ncontrol_tower_untracked=%d\nunreal_scene_untracked=%d\nother_untracked=%d\n", tracked, ct_tracked, other_tracked, untracked, ct_untracked, unreal_untracked, other_untracked)
}'","workdir":"/home/yashturkar/Workspace/spear","yield_time_ms":10000,"max_output_tokens":12000}
